.roc-paper h3{font:normal 26px/1.1 Georgia,serif;margin:17px 0 12px;letter-spacing:-.035em}
.roc-summary{font-size:12px;line-height:1.65;color:var(--roc-muted);max-width:240px}
.roc-paper-body{height:0;overflow:hidden;visibility:hidden;font-size:14px;line-height:1.75}
.roc-expand.is-open .roc-paper{width:min(100%,480px)}
.roc-expand.is-open .roc-paper-body{height:auto;visibility:visible;margin:22px 0 14px}
.roc-paper-body textarea{width:100%;resize:vertical;border:1px solid var(--roc-line);border-radius:5px;padding:10px;background:transparent;color:inherit;font:inherit;min-height:85px}
.roc-folder{height:330px;width:100%;max-width:560px;position:relative;isolation:isolate;margin:auto}
.roc-folder-back{position:absolute;left:50%;top:139px;width:224px;height:150px;transform:translateX(-50%);background:#b8bda2;border-radius:8px 18px 15px 15px;z-index:0}
.roc-folder-back:before{content:"";position:absolute;top:-13px;width:88px;height:25px;background:inherit;border-radius:9px 14px 0 0}
.roc-folder-items{position:absolute;inset:0;z-index:1}
.roc-folder-card{position:absolute;width:125px;height:155px;padding:16px;text-align:left;border:1px solid #d9d8cb;border-radius:4px;background:var(--roc-paper);box-shadow:0 4px 9px #2730200c;transform-origin:0 0;transition:transform .56s cubic-bezier(.22,.8,.25,1)}
.roc-folder-card strong{display:block;font:normal 20px/1.15 Georgia,serif;margin-top:18px}
.roc-card-content{display:block;margin-top:16px;font-size:10px;line-height:1.5;color:var(--roc-muted)}
.roc-folder-toggle{position:absolute;z-index:2;left:50%;top:169px;width:238px;height:128px;transform:translateX(-50%);border:1px solid #aab293;background:#c9cfb5;border-radius:7px 7px 15px 15px;text-align:left;padding:25px 21px;box-shadow:0 8px 14px #35402212;transform-origin:bottom;transition:transform .56s cubic-bezier(.22,.8,.25,1),background .3s}
.roc-folder-toggle>span:first-child{display:block;font-size:15px;margin-bottom:25px}.roc-folder-toggle>span:last-child{display:flex;justify-content:space-between;font-size:11px;color:#5d684d}.roc-folder-toggle b{font-size:18px;font-weight:400}
.roc-folder.is-open .roc-folder-toggle{transform:translateX(-50%) perspective(700px) rotateX(-18deg);background:#d7dcc6}
.roc-sources{position:relative;height:340px;width:100%;max-width:580px;margin:auto}
.roc-source-toggle{position:absolute;top:0;left:50%;transform:translateX(-50%);white-space:nowrap;z-index:12}
.roc-source-items{position:absolute;inset:55px 0 0}
.roc-source{position:absolute;width:146px;min-height:205px;border:1px solid #dbddd4;padding:20px 16px;background:var(--roc-paper);border-radius:5px;box-shadow:0 5px 14px #1e27100b;transform-origin:0 0;transition:transform .48s cubic-bezier(.22,.8,.25,1),opacity .3s}
.roc-source h3{font:normal 20px/1.15 Georgia,serif;letter-spacing:-.02em;margin:17px 0 12px}
.roc-source-content{font-size:11px;line-height:1.6;max-height:67px;overflow:hidden}
.roc-source-content input{width:100%;min-width:0;padding:6px;border:1px solid #bac2b0;background:transparent;font:inherit;border-radius:3px}
.roc-source.is-selected{width:min(80%,330px);min-height:225px}.roc-source.is-selected .roc-source-content{max-height:none}
.roc-sources.has-selection .roc-source:not(.is-selected){opacity:.2}
